package manifest

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"fmt"
	"io"
)

// These are generated, byte-for-byte gzip representations of the normative
// repository schemas. Tests verify that the embedded copies do not drift from
// schemas/. Keeping them in the public package makes validation work from a
// built binary without reaching into repository-internal packages or the
// network.
const manifestSchemaGZIPBase64 = ""
const identifiersSchemaGZIPBase64 = ""
const secretRefSchemaGZIPBase64 = ""

const currentManifestSchemaGZIPBase64 = ""

func bundledSchema(encoded string) ([]byte, error) {
	compressed, err := base64.StdEncoding.Strict().DecodeString(encoded)
	if err != nil {
		return nil, fmt.Errorf("decode embedded schema: %w", err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return nil, fmt.Errorf("open embedded schema: %w", err)
	}
	defer reader.Close()
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("inflate embedded schema: %w", err)
	}
	return data, nil
}
